    #Test DQ method
    @testset "Direct Quadrature" begin
    @test DQ(s -> SpatialLaplaceInversion.TestFunctions.Cohen1(s), 2.0, 100, 20000, γ = 0.01) ≈ 0.223070106757961 + 3.3475244809819287e-15im
    @test DQ_Array(s -> [[SpatialLaplaceInversion.TestFunctions.Cohen1(s), SpatialLaplaceInversion.TestFunctions.Cohen2(s)];; [SpatialLaplaceInversion.TestFunctions.Cohen3(s), SpatialLaplaceInversion.TestFunctions.Cohen4(s)]], 2.0, 100, 20000, γ = 0.01) ≈ [0.223070106757961 + 3.3475244809819287e-15im 0.3670741588770397 + 2.9403931251868295e-16im; -0.39527682889749355 - 4.7498658176094935e-15im 0.609534438436852 + 9.047363462113321e-17im]
    end

    #Test Weeks method
    @testset "Weeks" begin
      @test GenerateWeeksApproximation(SpatialLaplaceInversion.TestFunctions.Cohen1, 10, 1/2, 1).coefficients ≈ [0.7069738218268673, 0.3534611315626791, 0.08836164299072985, -0.04417617452478417, -0.07178511246950503, -0.04693513783742377, -0.013114005596703076, 0.007936972899272378, 0.013177829443379214, 0.008918073746578504, 0.002542217920055213]
      @test EvalWeeks(SpatialLaplaceInversion.Weeks.WeeksApproximation(SpatialLaplaceInversion.TestFunctions.Cohen1, 10, 0.5, 1.0, [0.7069738218268673, 0.3534611315626791, 0.08836164299072985, -0.04417617452478417, -0.07178511246950503, -0.04693513783742377, -0.013114005596703076, 0.007936972899272378, 0.013177829443379214, 0.008918073746578504, 0.002542217920055213], Float64), 2.0) ≈ 0.22002638341257189
    end

    #Test Gaver-Wynn-Rho method
    @testset "Gaver-Wynn-Rho" begin
      @test GWR(s -> SpatialLaplaceInversion.TestFunctions.Cohen1(s), 2.0, 10) ≈ 0.22388819868545348 + 0.0im
      @test GWR_array(s -> [[SpatialLaplaceInversion.TestFunctions.Cohen1(s), SpatialLaplaceInversion.TestFunctions.Cohen2(s)];; [SpatialLaplaceInversion.TestFunctions.Cohen3(s), SpatialLaplaceInversion.TestFunctions.Cohen4(s)]], 2.0, 10) ≈ [0.22388819868545348 + 0.0im 0.36787946200596916 + 0.0im; -0.37953903751703405 + 0.0im 0.6095163988345323 + 0.0im]
    end
